    for a in range ( len ( p ) - 2 , - 1 , - 1 ) :
        if p [ a ] < p [ a + 1 ] :
            b = len ( p ) - 1
            while True :
                if p [ b ] > p [ a ] :
                    t = p [ a ]
                    p [ a ] = p [ b ]
                    p [ b ] = t
                    a += 1
                    b = len ( p ) - 1
                    while a < b :
                        t = p [ a ]
